import json, os
H = "Hinojosa"
items = []
n = {"f":0,"m":0,"v":0,"c":0,"d":0,"r":0,"t":0}
def nid(k):
    n[k]+=1; return f"u07-{k}{n[k]:02d}"
def F(tema, p, r, e, d=1, et=()):
    items.append(dict(id=nid("f"), unidad=7, tema=tema, tipo="flashcard", pregunta=p, respuesta=r, explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))
def M(tema, p, ok, malas, e, d=2, et=()):
    items.append(dict(id=nid("m"), unidad=7, tema=tema, tipo="mcq", pregunta=p, opciones=[ok]+malas, correcta=ok, respuesta=ok, explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))
def V(tema, p, verdadero, jok, jmalas, e, d=2, et=()):
    c = "Verdadero" if verdadero else "Falso"
    items.append(dict(id=nid("v"), unidad=7, tema=tema, tipo="vf", pregunta=p, opciones=["Verdadero","Falso"], correcta=c, justificaciones=[jok]+jmalas, justificacionCorrecta=jok, respuesta=f"{c}. {jok}", explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))
def C(tema, relato, p, r, pk, e, d=2, et=()):
    items.append(dict(id=nid("c"), unidad=7, tema=tema, tipo="caso", relato=relato, pregunta=p, respuesta=r, puntosClave=pk, explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))
def D(tema, p, r, pk, e, d=3, et=()):
    items.append(dict(id=nid("d"), unidad=7, tema=tema, tipo="desarrollo", pregunta=p, respuesta=r, puntosClave=pk, explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))
def R(tema, p, pares, e, d=2, et=()):
    items.append(dict(id=nid("r"), unidad=7, tema=tema, tipo="matching", pregunta=p, pares=[{"a":a,"b":b} for a,b in pares], respuesta="; ".join(f"{a} → {b}" for a,b in pares), explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))
def T(tema, p, ev, e, d=2, et=()):
    items.append(dict(id=nid("t"), unidad=7, tema=tema, tipo="timeline", pregunta=p, eventos=[{"fecha":f,"texto":t} for f,t in ev], respuesta=" → ".join(f"{f}: {t}" for f,t in ev), explicacion=e, fuente=H, dificultad=d, etiquetas=list(et)))

